```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let notified = notifier::notify("heartbeat");
        if !notified {
            // The contract is `ensures notified == true`; a refused notification
            // must not produce a report that violates it. Trap instead.
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

I did not add the `aap:caps/state-rw@0.1.0` import or the `last-input` writes. The node's `with` clause is its entire authority and currently grants only the HTTP client, notifier, and wall clock. An approval mentioned in a request doesn't change the grant, and the graph definition hasn't been updated yet. Once the grant is in the graph, the import and the write can be added.

